solution.code:
const counter = (function () {
  let count = 0;
  return {
    increment() { count += 1; return count; },
    value() { return count; }
  };
})();

console.log(counter.increment());
console.log(counter.value());
console.log(counter.count);

brokenCode.code:
for (var i = 0; i < 3; i++) {
  // ... loop body
}
console.log(i); // 3 — i leaked out of the loop scope
// We wanted i to be confined to the loop

solution.code:
for (let i = 0; i < 3; i++) {
  // ... loop body
}
// console.log(i); // ReferenceError — i is block-scoped to the loop
console.log('loop done');

for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// logs 0, 1, 2 — each iteration has its own block-scoped i
